CREATE TABLE IF NOT EXISTS btm_posts (id INT AUTO_INCREMENT PRIMARY KEY, nick VARCHAR(32) NOT NULL, imagem VARCHAR(255) NOT NULL, legenda TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS btm_post_likes (post_id INT NOT NULL, nick VARCHAR(32) NOT NULL, PRIMARY KEY(post_id,nick));
CREATE TABLE IF NOT EXISTS btm_comments (id INT AUTO_INCREMENT PRIMARY KEY, post_id INT NOT NULL, nick VARCHAR(32) NOT NULL, comentario TEXT NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS denuncias (id INT AUTO_INCREMENT PRIMARY KEY, denunciante VARCHAR(32) NOT NULL, denunciado VARCHAR(32) NOT NULL, motivo VARCHAR(120) NOT NULL, descricao TEXT NOT NULL, prova VARCHAR(255), status VARCHAR(30) DEFAULT 'Pendente', admin VARCHAR(32) DEFAULT NULL, resposta TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS btm_musicas (id INT AUTO_INCREMENT PRIMARY KEY, nick VARCHAR(32) NOT NULL, titulo VARCHAR(120) NOT NULL, artista VARCHAR(120), mp3_url VARCHAR(500) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS btm_music_likes (musica_id INT NOT NULL, nick VARCHAR(32) NOT NULL, PRIMARY KEY(musica_id,nick));
CREATE TABLE IF NOT EXISTS btm_music_favoritos (musica_id INT NOT NULL, nick VARCHAR(32) NOT NULL, PRIMARY KEY(musica_id,nick));